//! Required LEGEND align DOMString reflection retains actual attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><legend id=legend align=MiXeD>Fallback legend</legend><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://legend-align.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn legend_align_canonical_accessor_descriptor_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),P=HTMLLegendElement.prototype,a=Object.getOwnPropertyDescriptor(P,'align');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get align'||a.set.name!=='set align'||Object.hasOwn(x,'align')||x.align!=='MiXeD'||x.textContent!=='Fallback legend')throw 'canonical legend align accessor';"#);}
#[test]
fn legend_align_native_domstring_aliases_old_values_and_absent_default(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),attr=x.getAttributeNode('align'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.align='A\ud800Z';var records=watch.takeRecords();if(x.align!=='A\ud800Z'||attr.value!==x.align||x.getAttributeNode('align')!==attr||records.length!==1||records[0].attributeName!=='align'||records[0].oldValue!=='MiXeD'||x.textContent!=='Fallback legend')throw 'exact legend align transaction';attr.nodeValue='unrestricted';if(x.align!=='unrestricted')throw 'ordinary string reflection';x.removeAttribute('align');if(x.align!==''||attr.ownerElement!==null||attr.value!=='unrestricted')throw 'removed align default';x.align=null;if(x.align!=='null'||document.getElementById('neighbor').value!=='seed')throw 'null DOMString conversion';"#);}
#[test]
fn legend_align_inert_exact_namespace_once_conversion_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:legend');if(!(x instanceof HTMLLegendElement)||x.align!=='')throw 'inert legend align default';var calls=0;x.align={toString:function(){calls++;x.setAttribute('align','author');return 'R\udfffZ';}};if(calls!==1||x.align!=='R\udfffZ'||x.getAttribute('align')!==x.align)throw 'once exact conversion';x.setAttributeNS('urn:foreign','align','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.align!=='R\udfffZ')throw 'exact null namespace align';var clone=x.cloneNode(false);if(clone.align!==x.align)throw 'namespace copy';x.removeAttributeNS('urn:foreign','align');x.removeAttributeNS(null,'ALIGN');var target=new Document(),caught=false,attr=x.getAttributeNode('align');try{target.importNode(x,false);}catch(e){caught=e.name==='NotSupportedError';}if(!caught||x.ownerDocument!==doc||x.getAttributeNode('align')!==attr||clone.getAttributeNode('align')===attr)throw 'guarded legend import preserves source';clone.align='independent';if(x.align!=='R\udfffZ'||attr.value!==x.align||clone.align!=='independent')throw 'independent copied align';"#);}

#[test]
fn legend_align_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),old=x.getAttributeNode('align'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.align={toString:function(){calls++;x.removeAttribute('align');x.setAttribute('align','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('align'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='MiXeD'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.align={toString:function(){x.setAttribute('align','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.align!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.align=Symbol('div');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.align!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.align=value;if(x.align!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='Fallback legend')throw 'metadata leaves displayed text';"#);
}

#[test]
fn legend_align_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),C=HTMLLegendElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'align'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElement('h1'),document.createElement('div'),document.getElementById('neighbor'),document.createElementNS('urn:foreign','legend'),new Document().createElementNS('http://www.w3.org/1999/xhtml','LEGEND')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'align',{value:'author',writable:true,configurable:true});if(x.align!=='author'||a.get.call(x)!=='MiXeD')throw 'canonical authority';a.set.call(x,'canonical');if(x.align!=='author'||x.getAttribute('align')!=='canonical')throw 'borrowed real setter';delete x.align;if(x.align!=='canonical'||Object.hasOwn(x,'align'))throw 'restored inherited reflection';delete window.HTMLLegendElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}

#[test]
fn legend_align_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLLegendElement,a=Object.getOwnPropertyDescriptor(C.prototype,'align'),calls=0;if(C===HTMLLegendElement||a.get.call(x)!=='MiXeD')throw 'captured data accessor';"#);p.set_location(&crate::navigation::address("https://other-legend-align.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://legend-align.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'data origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.

#[test]
fn legend_align_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.align='Long canonical \ud800 LEGEND alignment replacement';",r"x.setAttribute('align','Long canonical \ud800 LEGEND alignment replacement');",r"attr.value='Long canonical \ud800 LEGEND alignment replacement';",r"attr.nodeValue='Long canonical \ud800 LEGEND alignment replacement';",r"attr.textContent='Long canonical \ud800 LEGEND alignment replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','legend');x.setAttribute('align','MiXeD');"}else{"var x=document.getElementById('legend');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('align'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("value writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='MiXeD'||x.align!=='MiXeD'||watch.takeRecords().length)throw 'atomic value writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.align!=='Long canonical \ud800 LEGEND alignment replacement'||records.length!==1||records[0].oldValue!=='MiXeD'||records[0].attributeName!=='align'||x.getAttributeNode('align')!==attr)throw 'fresh value writer recovery';");
 }}}
}

#[test]
fn legend_align_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var data=new Document().createElementNS('http://www.w3.org/1999/xhtml','legend');data.align='A\ud800Z';");let Value::Host(object)=p.runtime.execute("data;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert data handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('legend').align='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("legend")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.legend_align_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.legend_align_get(object).is_ok());}}
}

#[test]
fn legend_align_attached_aliases_preserve_null_namespace_and_current_form(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),attr=x.getAttributeNode('align');for(var alias of ['value','nodeValue','textContent']){attr[alias]='R\ud800'+alias;if(x.align!==attr[alias]||x.getAttributeNode('align')!==attr)throw 'actual attached alias';}x.setAttributeNS('urn:other','align','foreign');x.setAttributeNS(null,'ALIGN','upper');if(x.align!=='R\ud800textContent'||x.form!==null)throw 'exact reflection and standalone form';"#);
}
#[test]
fn legend_align_writes_preserve_actual_fieldset_owner_and_first_legend_controls(){
 let mut d=crate::html::parse("<form id=owner><fieldset id=group disabled><legend id=legend align=initial>Group<input id=inside value=inside></legend><input id=outside value=outside></fieldset></form><form id=other></form>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);
 let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();
 run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('legend'),group=document.getElementById('group'),owner=document.getElementById('owner'),other=document.getElementById('other'),a=Object.getOwnPropertyDescriptor(HTMLLegendElement.prototype,'align');a.set.call(x,'R\udfffZ');if(x.form!==owner||a.get.call(x)!=='R\udfffZ'||group.firstChild!==x)throw 'actual owner and first legend';"#);
 assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
 run(&mut d,&mut f,&mut p,"group.setAttribute('form','other');x.align=null;if(x.form!==other||x.align!=='null'||document.getElementById('inside').form!==owner||document.getElementById('outside').form!==owner)throw 'independent current ownership';");
}
